#' Wrapper function to generate densMAP parameters
#'
#' @description The density-preservation knobs on top of the usual UMAP
#' parameters. densMAP adds `-lambda * Corr(log Ro, log Re)` to the UMAP loss,
#' where `Ro` is the local radius in the input space and `Re` the matching
#' radius in the embedding. Setting `lambda` to `0` recovers plain UMAP.
#'
#' @param lambda Numeric. Weight of the density term. `0` disables it. The
#' default is the densMAP reference value. Defaults to `2.0`.
#' @param frac Numeric. Fraction of the total epochs, at the end of the run,
#' over which the density term is active. Defaults to `0.3`.
#' @param var_shift Numeric. Additive shift on the variance of the embedding
#' log-radii. Defaults to `0.1`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item lambda - Numeric. Weight of the density term. `0` disables it. The
#'  default is the densMAP reference value. Defaults to `2.0`.
#'  \item frac - Numeric. Fraction of the total epochs, at the end of the run,
#'  over which the density term is active. Defaults to `0.3`.
#'  \item var_shift - Numeric. Additive shift on the variance of the embedding
#'  log-radii. Defaults to `0.1`.
#' }
#'
#' @references Narayan, Berger & Cho, Nat. Biotechnol., 2021
#'
#' @export
params_densmap <- function(
  lambda = 2.0,
  frac = 0.3,
  var_shift = 0.1
) {
  # Checks
  checkmate::qassert(lambda, "N1[0,)")
  checkmate::qassert(frac, "N1[0,1]")
  checkmate::qassert(var_shift, "N1[0,)")

  # Return
  list(
    lambda = lambda,
    frac = frac,
    var_shift = var_shift
  )
}

