#' Wrapper function to generate k-means parameters
#'
#' @param metric String. Distance metric to use. One of `c("euclidean",
#' "cosine")`. Defaults to `"euclidean"`.
#' @param max_iters Integer. Maximum number of iterations. Defaults to `1000L`.
#' @param batch_size Integer. Mini-batch size. Only used when `method =
#' "minibatch"`. Defaults to `4096L`.
#' @param drift_threshold Numeric. Below which centroid drift the mini-batch
#' k-means is considered converged. Only used when `method = "minibatch"`.
#' Defaults to `1e-04`.
#' @param lr_alpha Numeric. Learning rate decay for the mini-batch k-means.
#' Original paper uses `1.0`. Defaults to `1.0`.
#' @param init String. The initialisation of the centroids. One of
#' `c("parallel", "random")`. Defaults to `"parallel"`.
#' @param use_hamerly Boolean or `NULL`. Shall Hamerly's method be used (only if
#' `metric == "euclidean"`). Defaults to `NULL`.
#' @param use_gemm Boolean or `NULL`. Shall the GEMM path be used. Useful on
#' high dimensional data. If `NULL`, choice will be based on heuristics.
#' Defaults to `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item metric - String. Distance metric to use. One of `c("euclidean",
#'  "cosine")`. Defaults to `"euclidean"`.
#'  \item max_iters - Integer. Maximum number of iterations. Defaults to
#'  `1000L`.
#'  \item batch_size - Integer. Mini-batch size. Only used when `method =
#'  "minibatch"`. Defaults to `4096L`.
#'  \item drift_threshold - Numeric. Below which centroid drift the mini-batch
#'  k-means is considered converged. Only used when `method = "minibatch"`.
#'  Defaults to `1e-04`.
#'  \item lr_alpha - Numeric. Learning rate decay for the mini-batch k-means.
#'  Original paper uses `1.0`. Defaults to `1.0`.
#'  \item init - String. The initialisation of the centroids. One of
#'  `c("parallel", "random")`. Defaults to `"parallel"`.
#'  \item use_hamerly - Boolean or `NULL`. Shall Hamerly's method be used (only
#'  if `metric == "euclidean"`). Defaults to `NULL`.
#'  \item use_gemm - Boolean or `NULL`. Shall the GEMM path be used. Useful on
#'  high dimensional data. If `NULL`, choice will be based on heuristics.
#'  Defaults to `NULL`.
#' }
#'
#' @export
params_kmeans <- function(
  metric = c("euclidean", "cosine"),
  max_iters = 1000L,
  batch_size = 4096L,
  drift_threshold = 1e-04,
  lr_alpha = 1.0,
  init = c("parallel", "random"),
  use_hamerly = NULL,
  use_gemm = NULL
) {
  metric <- match.arg(metric)
  init <- match.arg(init)

  # Checks
  checkmate::assertChoice(metric, c("euclidean", "cosine"))
  checkmate::qassert(max_iters, "I1[1,)")
  checkmate::qassert(batch_size, "I1[1,)")
  checkmate::qassert(drift_threshold, "N1")
  checkmate::qassert(lr_alpha, "N1")
  checkmate::assertChoice(init, c("parallel", "random"))
  checkmate::qassert(use_hamerly, c("B1", "0"))
  checkmate::qassert(use_gemm, c("B1", "0"))

  # Return
  list(
    metric = metric,
    max_iters = max_iters,
    batch_size = batch_size,
    drift_threshold = drift_threshold,
    lr_alpha = lr_alpha,
    init = init,
    use_hamerly = use_hamerly,
    use_gemm = use_gemm
  )
}

#' Wrapper function to generate nearest neighbour parameters
